s.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[12]}}}},{"candidate":"a3e0a23d3c7caa28190314d8e9c47e6b86d5dad87183ee40d2e4ff47faa2361d","expected_status":"under_review","expected_payload":{"raw_text":"41. Paula foi convidada a comparecer à Delegacia Policial para\nsua oitiva como autora em relação ao crime de exposição ou\nabandono de recém-nascido, previsto no artigo 134, caput, do\nCódigo Penal. Após sua oitiva, os autos foram enviados à\nJustiça para seguir os trâmites processuais. Cumpridas todas\nas fases determinadas pela legislação, Paula foi denunciada\npelo Ministério Público, tendo o Magistrado rejeitado a peça\ninaugural. Nessa hipótese, deverá o Ministério Público\nA) aceitar a decisão de rejeição da denúncia nesse procedimento,\npor ser irrecorrível.\nB) recorrer da decisão por meio do recurso de apelação.\nC) recorrer da decisão por meio do recurso em sentido estrito.\nD) recorrer da decisão por meio de recurso inominado.\nE) recorrer da decisão por meio de um mandado de segurança.","item_number":41,"source_pages":[12],"answer_in_official_document":"B","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"41. Paula foi convidada a comparecer à Delegacia Policial para\nsua oitiva como autora em relação ao crime de exposição ou\nabandono de recém-nascido, previsto no artigo 134, caput, do\nCódigo Penal. Após sua oitiva, os autos foram enviados à\nJustiça para seguir os trâmites processuais. Cumpridas todas\nas fases determinadas pela legislação, Paula foi denunciada\npelo Ministério Público, tendo o Magistrado rejeitado a peça\ninaugural. Nessa hipótese, deverá o Ministério Público\nA) aceitar a decisão de rejeição da denúncia nesse procedimento,\npor ser irrecorrível.\nB) recorrer da decisão por meio do recurso de apelação.\nC) recorrer da decisão por meio do recurso em sentido estrito.\nD) recorrer da decisão por meio de recurso inominado.\nE) recorrer da decisão por meio de um mandado de segurança.","item_number":41,"source_pages":[12],"answer_in_official_document":"B","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"B","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/a3e0a23d3c7caa28190314d8e9c47e6b86d5dad87183ee40d2e4ff47faa2361d","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Recurso no Juizado Especial Criminal","observed_style":"caso_pratico","explanation":"A resposta B supõe incidência do rito da Lei 9.099 e sua apelação contra rejeição de denúncia, diferentemente da regra geral do CPP 581. É preciso conferir a pena atual do art. 134 e o rito aplicável antes de concluir a espécie recursal.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","fonte_especial_pendente"],"primary_evidence":[{"reference":"cp:134","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"2b18432ee78986caf1147257e5bffeb3efb83e82ee9e9870af39c651c35117da","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/134","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cpp:581","title":"Código de Processo Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"e6e68e8afc1da9aeac8970fb106d7d49e88eec11d67db3b704c8c6db65c2fe0f","excerpt_sha256":"6762dd7eb9b23038c0bd9a2dd3deb848c6ef5e02de8914f4e1810fd3b58129d9","excerpt_artifact":"fontes-e-excertos.json#/sources/cpp/excerpts/581","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[12]}}}},{"candidate":"b40437a4cde29ca3a753aeb293b1878c6ed48f2592b3d41ae875b5bb67c88551","expected_status":"under_review","expected_payload":{"raw_text":"42. Com base na Lei 9.099/95, analise as afirmativas a seguir:\nI. A competência do Juizado será determinada pelo lugar em que\nfoi praticada a infração penal.\nII. A conciliação será conduzida pelo Juiz ou por conciliador sob\nsua orientação.\nIII. Acolhendo a proposta de transação penal do Ministério Público\naceita pelo autor da infração, o Juiz aplicará a pena restritiva\nde direitos ou multa, que não importará em reincidência, sendo\nregistrada apenas para impedir novamente o mesmo benefício\nno prazo de cinco anos.\nIV. A autoridade policial que tomar conhecimento da ocorrência\nlavrará termo circunstanciado e o encaminhará imediatamente\nao Juizado.\nAssinale\nA) se apenas as afirmativas I, III e IV estiverem corretas.\nB) se apenas as afirmativas II e IV estiverem corretas.\nC) se apenas as afirmativas III e IV estiverem corretas.\nD) se todas as afirmativas estiverem corretas.\nE) se apenas as afirmativas II e III estiverem corretas.","item_number":42,"source_pages":[12],"answer_in_official_document":"D","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"42. Com base na Lei 9.099/95, analise as afirmativas a seguir:\nI. A competência do Juizado será determinada pelo lugar em que\nfoi praticada a infração penal.\nII. A conciliação será conduzida pelo Juiz ou por conciliador sob\nsua orientação.\nIII. Acolhendo a proposta de transação penal do Ministério Público\naceita pelo autor da infração, o Juiz aplicará a pena restritiva\nde direitos ou multa, que não importará em reincidência, sendo\nregistrada apenas para impedir novamente o mesmo benefício\nno prazo de cinco anos.\nIV. A autoridade policial que tomar conhecimento da ocorrência\nlavrará termo circunstanciado e o encaminhará imediatamente\nao Juizado.\nAssinale\nA) se apenas as afirmativas I, III e IV estiverem corretas.\nB) se apenas as afirmativas II e IV estiverem corretas.\nC) se apenas as afirmativas III e IV estiverem corretas.\nD) se todas as afirmativas estiverem corretas.\nE) se apenas as afirmativas II e III estiverem corretas.","item_number":42,"source_pages":[12],"answer_in_official_document":"D","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"D","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/b40437a4cde29ca3a753aeb293b1878c6ed48f2592b3d41ae875b5bb67c88551","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Regras do Juizado Especial Criminal","observed_style":"afirmativas","explanation":"A alternativa D depende do cotejo dos arts. 63, 69, 73 e 76 da Lei 9.099, incluindo registro da transação sem reincidência e prazo de cinco anos para nova concessão. A confirmação do texto especial permanece pendente.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","fonte_especial_pendente"],"primary_evidence":[],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[12]}}}},{"candidate":"94cf03a250e57fb0981770d181e88a9f775bc19763debfe0e93990d85635bfe5","expected_status":"under_review","expected_payload":{"raw_text":"43. A Lei 13.964/19, intitulada “Pacote Anticrime”, promoveu\nrecentemente várias alterações na legislação, sendo certo que\no Superior Tribunal de Justiça vem uniformizando sua\ninterpretação desses novos dispositivos legais.\nAcerca da jurisprudência recente sobre tema, é INCORRETO\nafirmar que\nA) é reconhecida a retroatividade do patamar estabelecido no art.\n112, V, da Lei 13.964/2019, àqueles apenados que, embora\ntenham cometido crime hediondo ou equiparado sem\nresultado morte, não sejam reincidentes em delito de natureza\nsemelhante.\nB) após o advento da Lei 13.964/2019, não é possível a\nconversão ex officio da prisão em flagrante em preventiva,\nmesmo nas situações em que não ocorre audiência de\ncustódia.\nC) o acordo de não persecução penal (ANPP) aplica-se a fatos\nocorridos antes da Lei 13.964/2019, desde que não recebida\na denúncia.\nD) a exigência de representação da vítima no crime de estelionato\nretroage aos processos cuja denúncia já foi oferecida.\nE) as inovações do Pacote Anticrime na Lei 9.296/1996 não\nalteraram o entendimento de que é lícita a prova consistente\nem gravação ambiental realizada por um dos interlocutores\nsem conhecimento do outro.","item_number":43,"source_pages":[13],"answer_in_official_document":"D","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"43. A Lei 13.964/19, intitulada “Pacote Anticrime”, promoveu\nrecentemente várias alterações na legislação, sendo certo que\no Superior Tribunal de Justiça vem uniformizando sua\ninterpretação desses novos dispositivos legais.\nAcerca da jurisprudência recente sobre tema, é INCORRETO\nafirmar que\nA) é reconhecida a retroatividade do patamar estabelecido no art.\n112, V, da Lei 13.964/2019, àqueles apenados que, embora\ntenham cometido crime hediondo ou equiparado sem\nresultado morte, não sejam reincidentes em delito de natureza\nsemelhante.\nB) após o advento da Lei 13.964/2019, não é possível a\nconversão ex officio da prisão em flagrante em preventiva,\nmesmo nas situações em que não ocorre audiência de\ncustódia.\nC) o acordo de não persecução penal (ANPP) aplica-se a fatos\nocorridos antes da Lei 13.964/2019, desde que não recebida\na denúncia.\nD) a exigência de representação da vítima no crime de estelionato\nretroage aos processos cuja denúncia já foi oferecida.\nE) as inovações do Pacote Anticrime na Lei 9.296/1996 não\nalteraram o entendimento de que é lícita a prova consistente\nem gravação ambiental realizada por um dos interlocutores\nsem conhecimento do outro.","item_number":43,"source_pages":[13],"answer_in_official_document":"D","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"D","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/94cf03a250e57fb0981770d181e88a9f775bc19763debfe0e93990d85635bfe5","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Retroatividade do Pacote Anticrime","observed_style":"jurisprudencia_em_alternativas","explanation":"O conjunto de teses é temporalmente sensível: a limitação histórica do ANPP ao não recebimento da denúncia exige cotejo com julgamentos posteriores, assim como representação no estelionato e cadeia de custódia. Não atestar apenas a letra D sem revisar todos os distratores.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","jurisprudencia_pendente","legislacao_e_teses_temporais"],"primary_evidence":[{"reference":"cpp:28A","title":"Código de Processo Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"e6e68e8afc1da9aeac8970fb106d7d49e88eec11d67db3b704c8c6db65c2fe0f","excerpt_sha256":"735fcdf27b03d99c0a5536a403f165363f250f5ad3092141fa445ced9aa1788a","excerpt_artifact":"fontes-e-excertos.json#/sources/cpp/excerpts/28A","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cpp:158A","title":"Código de Processo Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"e6e68e8afc1da9aeac8970fb106d7d49e88eec11d67db3b704c8c6db65c2fe0f","excerpt_sha256":"172bb10af1ecf75c9d01a3e9c28a605d2966fe930a5995a9c4848bdae42d3b80","excerpt_artifact":"fontes-e-excertos.json#/sources/cpp/excerpts/158A","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[13]}}}},{"candidate":"08f55c788c5e9f11b37976941cf95bb4cb56c6586c399f9f59cee77919e29051","expected_status":"under_review","expected_payload":{"raw_text":"44. Joelma e Godofredo são pescadores e foram surpreendidos\npescando em período de defeso, bem como utilizando\nartefatos de uso proibido (uma rede de pesca de uso proibido),\ncom dez camarões em uma bacia e mais dois camarões\npresos na rede proibida. O Ministério Público denunciou os\ndois pescadores pela prática de crime ambiental descrita no\nartigo 34 da Lei 9.605/98. Em relação ao tema, é correto\nafirmar que a jurisprudência do STJ\nA) admite a possibilidade de aplicação da insignificância aos\ndelitos ambientais quando demonstrada a ínfima ofensividade\nao bem ambiental tutelado, mesmo quando a conduta tenha\nocorrido durante o período de defeso, mas afasta tal tese\nquando da utilização de petrechos proibidos ou da apreensão\ndo pescado no momento do flagrante.\nB) admite a possibilidade de aplicação da insignificância aos\ndelitos ambientais quando demonstrada a ínfima ofensividade\nao bem ambiental tutelado, mesmo quando ocorra a\napreensão do pescado no momento do flagrante.\nC) não admite a possibilidade de aplicação da insignificância aos\ndelitos ambientais, ainda quando demonstrada a ínfima\nofensividade ao bem ambiental tutelado.\nD) admite a possibilidade de aplicação da insignificância aos\ndelitos ambientais quando demonstrada a ínfima ofensividade\nao bem ambiental tutelado, mesmo quando a conduta tenha\nocorrido durante o período de defeso e com petrechos\nproibidos.\nE) admite a possibilidade de aplicação da insignificância aos\ndelitos ambientais quando demonstrada a ínfima ofensividade\nao bem ambiental tutelado, mesmo quando a conduta for\nrealizada com petrechos proibidos.","item_number":44,"source_pages":[13],"answer_in_official_document":"A","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"44. Joelma e Godofredo são pescadores e foram surpreendidos\npescando em período de defeso, bem como utilizando\nartefatos de uso proibido (uma rede de pesca de uso proibido),\ncom dez camarões em uma bacia e mais dois camarões\npresos na rede proibida. O Ministério Público denunciou os\ndois pescadores pela prática de crime ambiental descrita no\nartigo 34 da Lei 9.605/98. Em relação ao tema, é correto\nafirmar que a jurisprudência do STJ\nA) admite a possibilidade de aplicação da insignificância aos\ndelitos ambientais quando demonstrada a ínfima ofensividade\nao bem ambiental tutelado, mesmo quando a conduta tenha\nocorrido durante o período de defeso, mas afasta tal tese\nquando da utilização de petrechos proibidos ou da apreensão\ndo pescado no momento do flagrante.\nB) admite a possibilidade de aplicação da insignificância aos\ndelitos ambientais quando demonstrada a ínfima ofensividade\nao bem ambiental tutelado, mesmo quando ocorra a\napreensão do pescado no momento do flagrante.\nC) não admite a possibilidade de aplicação da insignificância aos\ndelitos ambientais, ainda quando demonstrada a ínfima\nofensividade ao bem ambiental tutelado.\nD) admite a possibilidade de aplicação da insignificância aos\ndelitos ambientais quando demonstrada a ínfima ofensividade\nao bem ambiental tutelado, mesmo quando a conduta tenha\nocorrido durante o período de defeso e com petrechos\nproibidos.\nE) admite a possibilidade de aplicação da insignificância aos\ndelitos ambientais quando demonstrada a ínfima ofensividade\nao bem ambiental tutelado, mesmo quando a conduta for\nrealizada com petrechos proibidos.","item_number":44,"source_pages":[13],"answer_in_official_document":"A","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"A","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/08f55c788c5e9f11b37976941cf95bb4cb56c6586c399f9f59cee77919e29051","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Insignificância em crime ambiental","observed_style":"caso_pratico","explanation":"As alternativas dependem do alcance de precedentes sobre defeso, petrechos proibidos e ofensividade concreta. O gabarito A não pode ser transformado em proibição absoluta de insignificância sem cotejo atual no STJ.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","fonte_especial_e_jurisprudencia_pendentes"],"primary_evidence":[],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[13]}}}},{"candidate":"1044476937ad458dc64f4f57401e0a380463eb2269fa6820e9382110e3ea05c2","expected_status":"under_review","expected_payload":{"raw_text":"45. Mauro foi denunciado pela prática do delito de supressão de\ntributos, tipificado no artigo 1º, I, da Lei 8.137/90. Acontece\nque, desde que foi autuado pela autoridade fazendária, Mauro\nrecorreu da decisão, discordando do agente que o autuou. O\nprocesso administrativo ainda se encontra em andamento, não\ntendo a autoridade fazendária, até o momento, decidido de\nforma definitiva o lançamento do crédito tributário.\nAtento ao que foi narrado, bem como ao entendimento dos\nTribunais Superiores, assinale a alternativa correta.\nA) O crédito tributário não é elemento do tipo penal descrito no\nartigo 1º, inciso I, da Lei 8.137/90, razão pela qual não faz\nsentido aguardar o resultado do lançamento definitivo.\nB) Os crimes descritos no artigo 1º, incisos I a IV, da Lei 8.137/90\nsão delitos formais, razão pela qual não há qualquer ligação\ncom o lançamento do crédito definitivo pela autoridade\ntributária.\nC) Não se tipifica crime material contra a ordem tributária, previsto\nno art. 1º, incisos I a IV, da Lei 8.137/90, antes do lançamento\ndefinitivo do tributo.\nD) O Poder Judiciário não pode ficar vinculado a uma decisão da\nesfera administrativa, já que o correto é que o juiz fique adstrito\nàs provas constantes dos autos, na busca da verdade\nprocessual (“o que não está nos autos não está no meu\nmundo”).\nE) Pelo princípio da independência das instâncias, é possível que\na existência do fato alegadamente delituoso e a identificação\nda respectiva autoria se definam na esfera penal sem\nvinculação com a instância administrativa.","item_number":45,"source_pages":[13],"answer_in_official_document":"C","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"45. Mauro foi denunciado pela prática do delito de supressão de\ntributos, tipificado no artigo 1º, I, da Lei 8.137/90. Acontece\nque, desde que foi autuado pela autoridade fazendária, Mauro\nrecorreu da decisão, discordando do agente que o autuou. O\nprocesso administrativo ainda se encontra em andamento, não\ntendo a autoridade fazendária, até o momento, decidido de\nforma definitiva o lançamento do crédito tributário.\nAtento ao que foi narrado, bem como ao entendimento dos\nTribunais Superiores, assinale a alternativa correta.\nA) O crédito tributário não é elemento do tipo penal descrito no\nartigo 1º, inciso I, da Lei 8.137/90, razão pela qual não faz\nsentido aguardar o resultado do lançamento definitivo.\nB) Os crimes descritos no artigo 1º, incisos I a IV, da Lei 8.137/90\nsão delitos formais, razão pela qual não há qualquer ligação\ncom o lançamento do crédito definitivo pela autoridade\ntributária.\nC) Não se tipifica crime material contra a ordem tributária, previsto\nno art. 1º, incisos I a IV, da Lei 8.137/90, antes do lançamento\ndefinitivo do tributo.\nD) O Poder Judiciário não pode ficar vinculado a uma decisão da\nesfera administrativa, já que o correto é que o juiz fique adstrito\nàs provas constantes dos autos, na busca da verdade\nprocessual (“o que não está nos autos não está no meu\nmundo”).\nE) Pelo princípio da independência das instâncias, é possível que\na existência do fato alegadamente delituoso e a identificação\nda respectiva autoria se definam na esfera penal sem\nvinculação com a instância administrativa.","item_number":45,"source_pages":[13],"answer_in_official_document":"C","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"C","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/1044476937ad458dc64f4f57401e0a380463eb2269fa6820e9382110e3ea05c2","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Constituição de crédito tributário e tipicidade","observed_style":"caso_pratico","explanation":"A alternativa C reproduz tese vinculante sobre crimes materiais tributários dos incisos I a IV. Exige confirmação da súmula no STF e da Lei 8.137; a pendência administrativa não deve ser generalizada a todo crime tributário.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","fonte_especial_e_jurisprudencia_pendentes"],"primary_evidence":[],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[13]}}}},{"candidate":"1bd895c53f7e18ae5a016bc2e948739a8fc0251a98f83dd7732869affbff11d0","expected_status":"under_review","expected_payload":{"raw_text":"46. A Lei Maria da Penha se tornou um importante mecanismo\ncontra a violência doméstica e familiar contra a mulher, em\nconformidade com o disposto na Constituição Federal e nos\ntratados internacionais ratificados pelo Estado Brasileiro. Os\nTribunais Superiores já se manifestaram várias vezes sobre\nimportantes teses jurídicas a respeito da Lei Maria da Penha,\nque estão listadas nas alternativas a seguir, À EXCEÇÃO DE\nUMA. Assinale-a.\nA) Para a configuração da violência doméstica e familiar prevista\nno artigo 5º da Lei 11.340/2006 (Lei Maria da Penha), não se\nexige a coabitação entre autor e vítima.\nB) A Lei Maria da Penha pode incidir na agressão perpetrada pelo\nirmão contra a irmã na hipótese de violência praticada no\nâmbito familiar.\nC) A suspensão condicional do processo e a transação penal não\nse aplicam na hipótese de delitos sujeitos ao rito da Lei Maria\nda Penha.\nD) A prática de crime ou contravenção penal contra a mulher com\nviolência ou grave ameaça no ambiente doméstico\nimpossibilita a substituição da pena privativa de liberdade por\nrestritiva de direitos.\nE) É aplicável o princípio da insignificância nos crimes ou\ncontravenções penais praticados contra a mulher no âmbito\ndas relações domésticas.","item_number":46,"source_pages":[14],"answer_in_official_document":"E","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"46. A Lei Maria da Penha se tornou um importante mecanismo\ncontra a violência doméstica e familiar contra a mulher, em\nconformidade com o disposto na Constituição Federal e nos\ntratados internacionais ratificados pelo Estado Brasileiro. Os\nTribunais Superiores já se manifestaram várias vezes sobre\nimportantes teses jurídicas a respeito da Lei Maria da Penha,\nque estão listadas nas alternativas a seguir, À EXCEÇÃO DE\nUMA. Assinale-a.\nA) Para a configuração da violência doméstica e familiar prevista\nno artigo 5º da Lei 11.340/2006 (Lei Maria da Penha), não se\nexige a coabitação entre autor e vítima.\nB) A Lei Maria da Penha pode incidir na agressão perpetrada pelo\nirmão contra a irmã na hipótese de violência praticada no\nâmbito familiar.\nC) A suspensão condicional do processo e a transação penal não\nse aplicam na hipótese de delitos sujeitos ao rito da Lei Maria\nda Penha.\nD) A prática de crime ou contravenção penal contra a mulher com\nviolência ou grave ameaça no ambiente doméstico\nimpossibilita a substituição da pena privativa de liberdade por\nrestritiva de direitos.\nE) É aplicável o princípio da insignificância nos crimes ou\ncontravenções penais praticados contra a mulher no âmbito\ndas relações domésticas.","item_number":46,"source_pages":[14],"answer_in_official_document":"E","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"E","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/1bd895c53f7e18ae5a016bc2e948739a8fc0251a98f83dd7732869affbff11d0","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Violência doméstica e institutos despenalizadores","observed_style":"jurisprudencia_em_alternativas","explanation":"O item cobra a exceção a cinco teses dos tribunais. A letra E não dispensa conferir as súmulas atuais sobre insignificância, coabitação e substituição da pena; o contexto da Lei Maria da Penha é essencial.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","fonte_especial_e_jurisprudencia_pendentes"],"primary_evidence":[{"reference":"cp:44","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"cbdf66496c0b4be1645c3836d09ba4c72b47bda58ef8381ec9dd8a214787f36d","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/44","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[14]}}}},{"candidate":"348e823e20ea43fa71bbf96337454da34d7b55868e68757b9375f5f8b22f7de7","expected_status":"under_review","expected_payload":{"raw_text":"47. A gestante Márcia foi presa em flagrante pela prática do delito\nde aborto, que prevê pena de detenção de um a três anos,\nconforme previsão do artigo 124 do Código Penal. A\nmagistrada responsável pela ação penal concedeu liberdade\nprovisória a Márcia, na decisão que recebeu a denúncia feita\npelo Ministério Público. A defesa peticionou ao juízo\ndemonstrando que sua cliente cumpria todos os requisitos\npara que o Ministério Público oferecesse proposta de\nsuspensão condicional do processo, o que não foi feito.\nAcerca desse tema, é correto afirmar que\nA) a suspensão condicional do processo é instituto aplicável\napenas no procedimento sumaríssimo.\nB) embora previsto na Lei 9.099/95, a suspensão condicional do\nprocesso é aplicável a todos os crimes com pena mínima\nmenor ou igual a um ano, além dos demais requisitos legais.\nC) a suspensão condicional do processo não se aplica aos crimes\ndo rito do tribunal do júri.\nD) a natureza jurídica da suspensão condicional do processo é de\nato discricionário do Ministério Público, que a propõe quando\nbem entender ser justo.\nE) embora previsto na Lei 9.099/95, a suspensão condicional do\nprocesso é aplicável a todos os crimes com pena mínima\nmenor ou igual a dois anos, além dos demais requisitos legais.","item_number":47,"source_pages":[14],"answer_in_official_document":"B","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"47. A gestante Márcia foi presa em flagrante pela prática do delito\nde aborto, que prevê pena de detenção de um a três anos,\nconforme previsão do artigo 124 do Código Penal. A\nmagistrada responsável pela ação penal concedeu liberdade\nprovisória a Márcia, na decisão que recebeu a denúncia feita\npelo Ministério Público. A defesa peticionou ao juízo\ndemonstrando que sua cliente cumpria todos os requisitos\npara que o Ministério Público oferecesse proposta de\nsuspensão condicional do processo, o que não foi feito.\nAcerca desse tema, é correto afirmar que\nA) a suspensão condicional do processo é instituto aplicável\napenas no procedimento sumaríssimo.\nB) embora previsto na Lei 9.099/95, a suspensão condicional do\nprocesso é aplicável a todos os crimes com pena mínima\nmenor ou igual a um ano, além dos demais requisitos legais.\nC) a suspensão condicional do processo não se aplica aos crimes\ndo rito do tribunal do júri.\nD) a natureza jurídica da suspensão condicional do processo é de\nato discricionário do Ministério Público, que a propõe quando\nbem entender ser justo.\nE) embora previsto na Lei 9.099/95, a suspensão condicional do\nprocesso é aplicável a todos os crimes com pena mínima\nmenor ou igual a dois anos, além dos demais requisitos legais.","item_number":47,"source_pages":[14],"answer_in_official_document":"B","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"B","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/348e823e20ea43fa71bbf96337454da34d7b55868e68757b9375f5f8b22f7de7","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Suspensão condicional do processo","observed_style":"caso_pratico","explanation":"A pena mínima de até um ano, e não máxima de dois, é o parâmetro da Lei 9.099 para o instituto, além dos requisitos. O rito do júri não afasta o instituto por si; conferir o texto especial e o caso, sem prometer direito automático.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","fonte_especial_pendente"],"primary_evidence":[{"reference":"cp:124","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"a01f165af7d954358ad858f568151d0b9eb74a8ba4000fc718c0fd8e074e8f8d","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/124","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[14]}}}},{"candidate":"82e8bcea45756653556caa3db6219738ae00a6c6d1edfa61e9d7ff96965fbafb","expected_status":"under_review","expected_payload":{"raw_text":"48. Joelma foi encaminhada à Delegacia Policial pela suposta\nprática do delito descrito no artigo 7º, IX, da Lei 8.137/90,\ntendo em vista que, em seu estabelecimento comercial, havia\num único produto exposto que estava fora da validade prevista\npelo fabricante. De acordo com o previsto no referido artigo, é\nvedado “vender, ter em depósito para vender ou expor à venda\nou, de qualquer forma, entregar matéria-prima ou mercadoria,\nem condições impróprias ao consumo”. A investigação não\nrealizou qualquer exame pericial no produto, apenas se\nbaseando na validade exposta pelo fabricante para indiciar\nJoelma. Posteriormente, o Ministério Público denunciou\nJoelma exatamente pela conduta descrita acima.\nEm relação aos fatos narrados, é correto afirmar que\nA) a denúncia foi corretamente embasada no inquérito policial,\nque materializou a prova de que o produto estava fora da\nvalidade e, por óbvio, impróprio para consumo.\nB) se ocorreu a prova inequívoca de que o produto estava fora da\nvalidade, não há a necessidade de realização de exame\npericial de acordo com o CPP, pelo princípio da celeridade.\nC) a denúncia carece de justa causa, pois o crime mencionado\ndeixa vestígios materiais, sendo indispensável, portanto, a\nrealização de perícia para a sua comprovação.\nD) o Código de Processo Penal estabelece que o exame de corpo\nde delito é dispensável quando ocorra a prova inequívoca da\nmaterialidade.\nE) a Lei 8.137/90 determina que, no caso específico do\nenunciado, o exame pericial, excepcionalmente, pode não ser\nrealizado, comprovando-se a materialidade pela data de\nvalidade.","item_number":48,"source_pages":[14],"answer_in_official_document":"C","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"48. Joelma foi encaminhada à Delegacia Policial pela suposta\nprática do delito descrito no artigo 7º, IX, da Lei 8.137/90,\ntendo em vista que, em seu estabelecimento comercial, havia\num único produto exposto que estava fora da validade prevista\npelo fabricante. De acordo com o previsto no referido artigo, é\nvedado “vender, ter em depósito para vender ou expor à venda\nou, de qualquer forma, entregar matéria-prima ou mercadoria,\nem condições impróprias ao consumo”. A investigação não\nrealizou qualquer exame pericial no produto, apenas se\nbaseando na validade exposta pelo fabricante para indiciar\nJoelma. Posteriormente, o Ministério Público denunciou\nJoelma exatamente pela conduta descrita acima.\nEm relação aos fatos narrados, é correto afirmar que\nA) a denúncia foi corretamente embasada no inquérito policial,\nque materializou a prova de que o produto estava fora da\nvalidade e, por óbvio, impróprio para consumo.\nB) se ocorreu a prova inequívoca de que o produto estava fora da\nvalidade, não há a necessidade de realização de exame\npericial de acordo com o CPP, pelo princípio da celeridade.\nC) a denúncia carece de justa causa, pois o crime mencionado\ndeixa vestígios materiais, sendo indispensável, portanto, a\nrealização de perícia para a sua comprovação.\nD) o Código de Processo Penal estabelece que o exame de corpo\nde delito é dispensável quando ocorra a prova inequívoca da\nmaterialidade.\nE) a Lei 8.137/90 determina que, no caso específico do\nenunciado, o exame pericial, excepcionalmente, pode não ser\nrealizado, comprovando-se a materialidade pela data de\nvalidade.","item_number":48,"source_pages":[14],"answer_in_official_document":"C","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"C","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/82e8bcea45756653556caa3db6219738ae00a6c6d1edfa61e9d7ff96965fbafb","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Perícia em produto impróprio ao consumo","observed_style":"caso_pratico","explanation":"A letra C depende da incidência do art. 158 e da tese específica sobre mercadoria vencida. A discussão de dispensabilidade por outros elementos não pode ser resolvida apenas pela fórmula geral corpo de delito obrigatório.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","fonte_especial_e_jurisprudencia_pendentes"],"primary_evidence":[{"reference":"cpp:158","title":"Código de Processo Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"e6e68e8afc1da9aeac8970fb106d7d49e88eec11d67db3b704c8c6db65c2fe0f","excerpt_sha256":"7e655b58b01f0f10c1f71d1bb1d20ab9561cf489c9fd2f20425c908b6801c74a","excerpt_artifact":"fontes-e-excertos.json#/sources/cpp/excerpts/158","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[14]}}}},{"candidate":"832e0fa667899eb8aff70d590288314a92950a546e4b4a8b7b47ce4a0b748142","expected_status":"under_review","expected_payload":{"raw_text":"49. De acordo com a Constituição Federal, compete ao Superior\nTribunal de Justiça a uniformização da interpretação da lei\nfederal em todo o Brasil. É de responsabilidade do STJ a\nsolução definitiva dos casos criminais que não envolvam\nmatéria constitucional nem a justiça especializada. Em relação\nao Estatuto do Desarmamento, o Superior Tribunal de Justiça\njá teve oportunidade de se manifestar várias vezes,\nreformando seu entendimento sobre a matéria. Assinale a\nafirmativa que NÃO corrobore o entendimento desse tribunal\nem relação ao tema proposto.\nA) A\napreensão\nde\nínfima\nquantidade\nde\nmunição\ndesacompanhada de arma de fogo, excepcionalmente, a\ndepender da análise do caso concreto, pode levar ao\nreconhecimento de atipicidade da conduta, diante da ausência\nde exposição de risco ao bem jurídico tutelado pela norma.\nB) O crime de tráfico internacional de arma de fogo, acessório ou\nmunição, tipificado no art. 18 da Lei 10.826/03, é de perigo\nabstrato ou de mera conduta e visa a proteger a segurança\npública e a paz social.\nC) O simples fato de possuir ou portar munição caracteriza os\ndelitos previstos nos arts. 12, 14 e 16 da Lei 10.826/2003, por\nse tratar de crime de perigo abstrato e de mera conduta, sendo\nprescindível a demonstração de lesão ou de perigo concreto\nao bem jurídico tutelado, que é a incolumidade pública.\nD) O crime de comércio ilegal de arma de fogo, acessório ou\nmunição (art. 17 da Lei 10.826/2003) é delito de tipo misto\nalternativo e de perigo concreto, não bastando para sua\ncaracterização a prática de um dos núcleos do tipo penal,\nsendo imprescindível a demonstração de lesão ou de perigo\nconcreto ao bem jurídico tutelado, que é a incolumidade\npública.\nE) Demonstrada por laudo pericial a inaptidão da arma de fogo\npara o disparo, é atípica a conduta de portar ou de possuir\narma de fogo, diante da ausência de afetação do bem jurídico\nincolumidade pública, tratando-se de crime impossível pela\nineficácia absoluta do meio.","item_number":49,"source_pages":[15],"answer_in_official_document":"D","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"49. De acordo com a Constituição Federal, compete ao Superior\nTribunal de Justiça a uniformização da interpretação da lei\nfederal em todo o Brasil. É de responsabilidade do STJ a\nsolução definitiva dos casos criminais que não envolvam\nmatéria constitucional nem a justiça especializada. Em relação\nao Estatuto do Desarmamento, o Superior Tribunal de Justiça\njá teve oportunidade de se manifestar várias vezes,\nreformando seu entendimento sobre a matéria. Assinale a\nafirmativa que NÃO corrobore o entendimento desse tribunal\nem relação ao tema proposto.\nA) A\napreensão\nde\nínfima\nquantidade\nde\nmunição\ndesacompanhada de arma de fogo, excepcionalmente, a\ndepender da análise do caso concreto, pode levar ao\nreconhecimento de atipicidade da conduta, diante da ausência\nde exposição de risco ao bem jurídico tutelado pela norma.\nB) O crime de tráfico internacional de arma de fogo, acessório ou\nmunição, tipificado no art. 18 da Lei 10.826/03, é de perigo\nabstrato ou de mera conduta e visa a proteger a segurança\npública e a paz social.\nC) O simples fato de possuir ou portar munição caracteriza os\ndelitos previstos nos arts. 12, 14 e 16 da Lei 10.826/2003, por\nse tratar de crime de perigo abstrato e de mera conduta, sendo\nprescindível a demonstração de lesão ou de perigo concreto\nao bem jurídico tutelado, que é a incolumidade pública.\nD) O crime de comércio ilegal de arma de fogo, acessório ou\nmunição (art. 17 da Lei 10.826/2003) é delito de tipo misto\nalternativo e de perigo concreto, não bastando para sua\ncaracterização a prática de um dos núcleos do tipo penal,\nsendo imprescindível a demonstração de lesão ou de perigo\nconcreto ao bem jurídico tutelado, que é a incolumidade\npública.\nE) Demonstrada por laudo pericial a inaptidão da arma de fogo\npara o disparo, é atípica a conduta de portar ou de possuir\narma de fogo, diante da ausência de afetação do bem jurídico\nincolumidade pública, tratando-se de crime impossível pela\nineficácia absoluta do meio.","item_number":49,"source_pages":[15],"answer_in_official_document":"D","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"D","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/832e0fa667899eb8aff70d590288314a92950a546e4b4a8b7b47ce4a0b748142","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Crimes de armas e perigo abstrato","observed_style":"jurisprudencia_em_alternativas","explanation":"O item exige cotejo das cinco teses, especialmente a distinção entre perigo concreto e abstrato e a excepcional insignificância de munição. A lei especial e os precedentes do STJ ainda precisam de confirmação.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","fonte_especial_e_jurisprudencia_pendentes"],"primary_evidence":[],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[15]}}}},{"candidate":"3962ff99dbe7a7fa35bdf515f24ff2eef26b38513edabfedb04f3cb1b6ad6819","expected_status":"under_review","expected_payload":{"raw_text":"50. Carlos está sendo investigado por crime de lavagem de\ndinheiro tipificado na Lei 9.613/98 e resolve procurar um\nadvogado especialista na matéria para lhe esclarecer como os\nTribunais Superiores vêm se posicionando acerca da\ncomplexidade do tema. O advogado fez várias ponderações e\nesclarecimentos a Carlos.\nNesse cenário, assinale a afirmativa INCORRETA.\nA) O reconhecimento da extinção da punibilidade pela prescrição\nda infração penal antecedente não implica atipicidade do delito\nde lavagem (art. 1º da Lei 9.613/1998).\nB) A incidência simultânea do reconhecimento da continuidade\ndelitiva (art. 70 do CP) e da majorante prevista no §4º do art.\n1º da Lei 9.613/1998, nos crimes de lavagem de dinheiro,\nacarreta bis in idem.\nC) É possível o deferimento de medida assecuratória em desfavor\nde pessoa jurídica que se beneficia de produtos decorrentes\ndo crime de lavagem, ainda que não integre o polo passivo de\ninvestigação ou ação penal.\nD) A tipificação do crime de lavagem de dinheiro depende da\nexistência de uma infração penal antecedente; portanto, não é\npossível a autolavagem, isto é, a imputação simultânea, ao\nmesmo réu, da infração antecedente e do crime de lavagem.\nE) Nos crimes de lavagem ou ocultação de bens, direitos e\nvalores, é legítima a exasperação da pena-base pela\nvaloração negativa das consequências do crime em\ndecorrência da movimentação de expressiva quantia de\nrecursos, que extrapole o elemento natural do tipo.","item_number":50,"source_pages":[15],"answer_in_official_document":"D","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"50. Carlos está sendo investigado por crime de lavagem de\ndinheiro tipificado na Lei 9.613/98 e resolve procurar um\nadvogado especialista na matéria para lhe esclarecer como os\nTribunais Superiores vêm se posicionando acerca da\ncomplexidade do tema. O advogado fez várias ponderações e\nesclarecimentos a Carlos.\nNesse cenário, assinale a afirmativa INCORRETA.\nA) O reconhecimento da extinção da punibilidade pela prescrição\nda infração penal antecedente não implica atipicidade do delito\nde lavagem (art. 1º da Lei 9.613/1998).\nB) A incidência simultânea do reconhecimento da continuidade\ndelitiva (art. 70 do CP) e da majorante prevista no §4º do art.\n1º da Lei 9.613/1998, nos crimes de lavagem de dinheiro,\nacarreta bis in idem.\nC) É possível o deferimento de medida assecuratória em desfavor\nde pessoa jurídica que se beneficia de produtos decorrentes\ndo crime de lavagem, ainda que não integre o polo passivo de\ninvestigação ou ação penal.\nD) A tipificação do crime de lavagem de dinheiro depende da\nexistência de uma infração penal antecedente; portanto, não é\npossível a autolavagem, isto é, a imputação simultânea, ao\nmesmo réu, da infração antecedente e do crime de lavagem.\nE) Nos crimes de lavagem ou ocultação de bens, direitos e\nvalores, é legítima a exasperação da pena-base pela\nvaloração negativa das consequências do crime em\ndecorrência da movimentação de expressiva quantia de\nrecursos, que extrapole o elemento natural do tipo.","item_number":50,"source_pages":[15],"answer_in_official_document":"D","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"D","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/3962ff99dbe7a7fa35bdf515f24ff2eef26b38513edabfedb04f3cb1b6ad6819","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Lavagem e autolavagem","observed_style":"jurisprudencia_em_alternativas","explanation":"A alternativa D enuncia a tese histórica incorreta sobre impossibilidade de autolavagem. Há ainda referência suspeita de continuidade delitiva ao art. 70 em B, que trata de concurso formal; conferir o PDF e os precedentes sem corrigir silenciosamente a fonte.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","fonte_especial_e_jurisprudencia_pendentes","referencia_legal_inconsistente"],"primary_evidence":[{"reference":"cp:70","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"5f8925868b28082225a1cfeedadd553587fcfded21543da4a3ec1b6678d934cc","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/70","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cp:71","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"d0029a463765c934636b75e6fcd40cac0262bf976735ae73bba74db0f750fbe4","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/71","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[15]}}}},{"candidate":"9d07c5560abc189edfc488f48a1f297b18d774be54cc5f8138d972bc5584b469","expected_status":"under_review","expected_payload":{"raw_text":"51. A prova testemunhal é um dos mais importantes meios de\nprova previstos na legislação processual penal. O grande\nprocessualista Carnelutti, na obra Lições sobre o Processo\nPenal, registrou que “as testemunhas encontram-se no\nambiente do delito e o juiz, pelo contrário, no ambiente do\njuízo”. Portanto, a testemunha tem o poder de transportar o juiz\npara o universo do delito, seu local e os agentes envolvidos na\natividade criminosa. Nas alternativas a seguir, há algumas\nteses jurídicas exaradas pelo Superior Tribunal de Justiça a\nrespeito desse tema.\nNesse cenário, assinale a afirmativa INCORRETA, no tocante\nà posição do STJ.\nA) É possível o arrolamento de testemunhas pelo assistente de\nacusação (art. 271 do Código de Processo Penal), desde que\nrespeitado o limite de 5 (cinco) pessoas previsto no art. 422 do\nCPP.\nB) Em delitos sexuais, comumente praticados às ocultas, a\npalavra da vítima possui especial relevância, desde que esteja\nem consonância com as demais provas acostadas aos autos.\nC) É possível a antecipação da colheita da prova testemunhal,\ncom base no art. 366 do CPP, nas hipóteses em que as\ntestemunhas são policiais, tendo em vista a relevante\nprobabilidade de esvaziamento da prova pela natureza da\natuação profissional, marcada pelo contato diário com fatos\ncriminosos.\nD) Há cerceamento de defesa quando a decisão indefere a oitiva\nde testemunhas residentes em outro país.\nE) Nos delitos praticados em ambiente doméstico e familiar,\ngeralmente praticados à clandestinidade, sem a presença de\ntestemunhas, a palavra da vítima possui especial relevância,\nnotadamente quando corroborada por outros elementos\nprobatórios acostados aos autos.","item_number":51,"source_pages":[16],"answer_in_official_document":"D","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"51. A prova testemunhal é um dos mais importantes meios de\nprova previstos na legislação processual penal. O grande\nprocessualista Carnelutti, na obra Lições sobre o Processo\nPenal, registrou que “as testemunhas encontram-se no\nambiente do delito e o juiz, pelo contrário, no ambiente do\njuízo”. Portanto, a testemunha tem o poder de transportar o juiz\npara o universo do delito, seu local e os agentes envolvidos na\natividade criminosa. Nas alternativas a seguir, há algumas\nteses jurídicas exaradas pelo Superior Tribunal de Justiça a\nrespeito desse tema.\nNesse cenário, assinale a afirmativa INCORRETA, no tocante\nà posição do STJ.\nA) É possível o arrolamento de testemunhas pelo assistente de\nacusação (art. 271 do Código de Processo Penal), desde que\nrespeitado o limite de 5 (cinco) pessoas previsto no art. 422 do\nCPP.\nB) Em delitos sexuais, comumente praticados às ocultas, a\npalavra da vítima possui especial relevância, desde que esteja\nem consonância com as demais provas acostadas aos autos.\nC) É possível a antecipação da colheita da prova testemunhal,\ncom base no art. 366 do CPP, nas hipóteses em que as\ntestemunhas são policiais, tendo em vista a relevante\nprobabilidade de esvaziamento da prova pela natureza da\natuação profissional, marcada pelo contato diário com fatos\ncriminosos.\nD) Há cerceamento de defesa quando a decisão indefere a oitiva\nde testemunhas residentes em outro país.\nE) Nos delitos praticados em ambiente doméstico e familiar,\ngeralmente praticados à clandestinidade, sem a presença de\ntestemunhas, a palavra da vítima possui especial relevância,\nnotadamente quando corroborada por outros elementos\nprobatórios acostados aos autos.","item_number":51,"source_pages":[16],"answer_in_official_document":"D","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"D","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/9d07c5560abc189edfc488f48a1f297b18d774be54cc5f8138d972bc5584b469","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Prova testemunhal e cerceamento","observed_style":"jurisprudencia_em_alternativas","explanation":"D formula nulidade de modo genérico. O indeferimento exige avaliar pertinência, motivação e regras de cooperação, não simples residência no exterior. As demais teses do STJ também precisam de conferência atual.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","jurisprudencia_pendente"],"primary_evidence":[{"reference":"cpp:222A","title":"Código de Processo Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"e6e68e8afc1da9aeac8970fb106d7d49e88eec11d67db3b704c8c6db65c2fe0f","excerpt_sha256":"82cd7c4064cf6d7a199349c113f3e1a22f04e75c9236e79a14bb26223a92e379","excerpt_artifact":"fontes-e-excertos.json#/sources/cpp/excerpts/222A","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cpp:366","title":"Código de Processo Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"e6e68e8afc1da9aeac8970fb106d7d49e88eec11d67db3b704c8c6db65c2fe0f","excerpt_sha256":"b8e7edb4654424e33b5b4f98787b6fefdd286555f64f96e2ce1f2bb4ee2df3a9","excerpt_artifact":"fontes-e-excertos.json#/sources/cpp/excerpts/366","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[16]}}}},{"candidate":"f099ced1a5995e99e3223464a57f2702904b1aa7b91296e7fc4d85814f105807","expected_status":"under_review","expected_payload":{"raw_text":"52. Analise as afirmativas a seguir:\nI. A prova da alegação incumbirá a quem a fizer, sendo, porém,\nfacultado ao juiz de ofício determinar, no curso da instrução,\nou antes de proferir sentença, a realização de diligências para\ndirimir dúvida sobre ponto relevante.\nII. Dar-se-á prioridade à realização do exame de corpo de delito\nquando se tratar de crime que envolva violência doméstica e\nfamiliar contra mulher.\nIII. A acareação será admitida entre acusados, entre acusado e\ntestemunha, entre testemunhas, entre acusado ou testemunha\ne a pessoa ofendida, e entre as pessoas ofendidas, sempre\nque divergirem, em suas declarações, sobre fatos ou\ncircunstâncias relevantes.\nIV. São proibidas de depor as pessoas que, em razão de função,\nministério, ofício ou profissão, devam guardar segredo, salvo\nse desobrigadas pela parte interessada, oportunidade em que\nestarão obrigadas a depor.\nAssinale\nA) se apenas as afirmativas I, III e IV estiverem corretas.\nB) se apenas as afirmativas II, III e IV estiverem corretas.\nC) se apenas as afirmativas I, II, III estiverem corretas.\nD) se apenas as afirmativas III e IV estiverem corretas.\nE) se todas as afirmativas estiverem corretas.","item_number":52,"source_pages":[16],"answer_in_official_document":"C","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"52. Analise as afirmativas a seguir:\nI. A prova da alegação incumbirá a quem a fizer, sendo, porém,\nfacultado ao juiz de ofício determinar, no curso da instrução,\nou antes de proferir sentença, a realização de diligências para\ndirimir dúvida sobre ponto relevante.\nII. Dar-se-á prioridade à realização do exame de corpo de delito\nquando se tratar de crime que envolva violência doméstica e\nfamiliar contra mulher.\nIII. A acareação será admitida entre acusados, entre acusado e\ntestemunha, entre testemunhas, entre acusado ou testemunha\ne a pessoa ofendida, e entre as pessoas ofendidas, sempre\nque divergirem, em suas declarações, sobre fatos ou\ncircunstâncias relevantes.\nIV. São proibidas de depor as pessoas que, em razão de função,\nministério, ofício ou profissão, devam guardar segredo, salvo\nse desobrigadas pela parte interessada, oportunidade em que\nestarão obrigadas a depor.\nAssinale\nA) se apenas as afirmativas I, III e IV estiverem corretas.\nB) se apenas as afirmativas II, III e IV estiverem corretas.\nC) se apenas as afirmativas I, II, III estiverem corretas.\nD) se apenas as afirmativas III e IV estiverem corretas.\nE) se todas as afirmativas estiverem corretas.","item_number":52,"source_pages":[16],"answer_in_official_document":"C","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"C","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/f099ced1a5995e99e3223464a57f2702904b1aa7b91296e7fc4d85814f105807","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Provas e sigilo profissional","observed_style":"afirmativas","explanation":"CPP 207 permite o depoimento após desobrigação se a pessoa quiser testemunhar, não cria obrigação automática. I deve ser lida com a delimitação atual das diligências suplementares pelo STF; o gabarito C é histórico.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","confronto_jurisprudencial_parcial"],"primary_evidence":[{"reference":"cpp:156","title":"Código de Processo Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"e6e68e8afc1da9aeac8970fb106d7d49e88eec11d67db3b704c8c6db65c2fe0f","excerpt_sha256":"41acc0ee369340f1e826cbfcafffcc1ed25d1bc317f7c7553c6a4f39bf2d5f6e","excerpt_artifact":"fontes-e-excertos.json#/sources/cpp/excerpts/156","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cpp:158","title":"Código de Processo Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"e6e68e8afc1da9aeac8970fb106d7d49e88eec11d67db3b704c8c6db65c2fe0f","excerpt_sha256":"7e655b58b01f0f10c1f71d1bb1d20ab9561cf489c9fd2f20425c908b6801c74a","excerpt_artifact":"fontes-e-excertos.json#/sources/cpp/excerpts/158","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cpp:207","title":"Código de Processo Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"e6e68e8afc1da9aeac8970fb106d7d49e88eec11d67db3b704c8c6db65c2fe0f","excerpt_sha256":"402762fdd879b2da7e172efc7c1a1189c9aa89e45bc1f6ed715393087902db37","excerpt_artifact":"fontes-e-excertos.json#/sources/cpp/excerpts/207","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cpp:229","title":"Código de Processo Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"e6e68e8afc1da9aeac8970fb106d7d49e88eec11d67db3b704c8c6db65c2fe0f","excerpt_sha256":"574c4e9e42e3df38812075fc0dafa10e43c2dfed54229c66656cab8df1f61169","excerpt_artifact":"fontes-e-excertos.json#/sources/cpp/excerpts/229","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"stf6298","title":"Dispositivo de julgamento de 24/08/2023 da ADI 6.298","url":"https://portal.stf.jus.br/processos/downloadTexto.asp?id=5850380&ext=RTF","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"4ee04113e868696c5888451be65bfc143846d64480c7f39bd01bdcc029761754","excerpt_sha256":"9c0f4b2207108f698e5a7f5ef0ef874b9021757d04c8c88d4c55b25159a835d4","excerpt_artifact":"fontes-e-excertos.json#/sources/stf6298/excerpts/document","scope":"Dispositivo integral consultado, não acórdão integral"}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[16]}}}},{"candidate":"0523c129106fd973c0e93a01b88945c340e548886ac7568b3deca612a03a16ef","expected_status":"under_review","expected_payload":{"raw_text":"53. A doutrina determina que princípios são as regras primeiras;\nsão as premissas de todo um sistema de dogmática jurídico-\nprocessual penal. Parte da doutrina aponta esse princípio\ncomo o escopo primordial do processo penal. Trata-se dos\nelementos probatórios lícitos juntados aos autos do processo\npara serem apreciados pelo juiz e valorados no ato da\nsentença, a fim de se determinar quem foi de encontro ao\ncomando da norma e por que o fez.\nPela narrativa acima, estamos diante de qual princípio\nprocessual?\nA) Publicidade.\nB) Presunção de inocência.\nC) Verdade processual.\nD) Razoabilidade de duração do processo.\nE) Favor rei.","item_number":53,"source_pages":[16],"answer_in_official_document":"C","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"53. A doutrina determina que princípios são as regras primeiras;\nsão as premissas de todo um sistema de dogmática jurídico-\nprocessual penal. Parte da doutrina aponta esse princípio\ncomo o escopo primordial do processo penal. Trata-se dos\nelementos probatórios lícitos juntados aos autos do processo\npara serem apreciados pelo juiz e valorados no ato da\nsentença, a fim de se determinar quem foi de encontro ao\ncomando da norma e por que o fez.\nPela narrativa acima, estamos diante de qual princípio\nprocessual?\nA) Publicidade.\nB) Presunção de inocência.\nC) Verdade processual.\nD) Razoabilidade de duração do processo.\nE) Favor rei.","item_number":53,"source_pages":[16],"answer_in_official_document":"C","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"C","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/0523c129106fd973c0e93a01b88945c340e548886ac7568b3deca612a03a16ef","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Verdade processual","observed_style":"teoria_doutrinaria","explanation":"O gabarito C usa a verdade construída a partir de elementos lícitos do processo. Não justificar busca ilimitada de verdade real em detrimento de contraditório, imparcialidade e proibição de prova ilícita. Falta fonte doutrinária para certificação da nomenclatura.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","doutrina_pendente"],"primary_evidence":[{"reference":"cpp:155","title":"Código de Processo Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-194