ter_checked":false,"historical_answer_letter":"B","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/f9b9ec78039862882b9502900184d53ea4d0a728396eb18867218dc4d562361a","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Recusa de depor por parentes","observed_style":"caso_pratico","explanation":"CPP 206 enumera os familiares que podem recusar-se e a ressalva de impossibilidade de obter/integrar a prova de outro modo. A vedação por sigilo profissional do art. 207 é instituto distinto.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo"],"primary_evidence":[{"reference":"cpp:206","title":"Código de Processo Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"e6e68e8afc1da9aeac8970fb106d7d49e88eec11d67db3b704c8c6db65c2fe0f","excerpt_sha256":"870cfbb82af721ad1774540d365f250d0e6449fcb78243dd18b73e5b4acdd1f5","excerpt_artifact":"fontes-e-excertos.json#/sources/cpp/excerpts/206","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cpp:207","title":"Código de Processo Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"e6e68e8afc1da9aeac8970fb106d7d49e88eec11d67db3b704c8c6db65c2fe0f","excerpt_sha256":"402762fdd879b2da7e172efc7c1a1189c9aa89e45bc1f6ed715393087902db37","excerpt_artifact":"fontes-e-excertos.json#/sources/cpp/excerpts/207","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[19]}}}},{"candidate":"e43ddadeaede233fdd62b5d9d1b54b7f81b53ee63ecc067f92f7cd417dc34a25","expected_status":"under_review","expected_payload":{"raw_text":"61. Carlos foi condenado a uma pena de mais de dez anos de\nreclusão, tendo a sentença determinado o cumprimento da\npena em regime inicialmente fechado. Transitada em julgado\na sentença penal condenatória, iniciou-se o processo de\nexecução de pena, tendo Carlos se recolhido à prisão.\nCumpridos os requisitos subjetivos e objetivos para a obtenção\nda progressão de regime, o advogado de Carlos ingressou\ncom o pedido perante o Juízo de Execução. Deferida a\nprogressão para o regime menos rigoroso, semiaberto, a\nexecução continuou a cumprir seu papel. Passados mais\nalguns anos, Carlos cumpriu o prazo para mais uma\nprogressão de regime.\nNessa hipótese, assinale a alternativa correta.\nA) A legislação determina um prazo de suspensão da contagem de\nprazo após o deferimento da primeira progressão de regime para\nque o apenado possa começar novamente a contagem do prazo\npara o segundo benefício.\nB) A legislação determina um prazo de interrupção da contagem de\nprazo após o deferimento da primeira progressão de regime para\nque o apenado possa começar novamente a contagem do prazo\npara o segundo benefício.\nC) O cálculo de pena para uma posterior progressão de regime de\nCarlos para o regime aberto deve ser feito sobre o total da pena\nimposta na sentença.\nD) O cálculo de pena para uma posterior progressão de regime de\nCarlos para o regime aberto deve ser feito sobre o total da pena\nimposta na sentença, após o período de suspensão da\ncontagem do prazo.\nE) O cálculo de pena para uma posterior progressão de regime de\nCarlos para o regime aberto deve ser feito sobre o tempo de\npena que resta a cumprir.","item_number":61,"source_pages":[19],"answer_in_official_document":"E","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"61. Carlos foi condenado a uma pena de mais de dez anos de\nreclusão, tendo a sentença determinado o cumprimento da\npena em regime inicialmente fechado. Transitada em julgado\na sentença penal condenatória, iniciou-se o processo de\nexecução de pena, tendo Carlos se recolhido à prisão.\nCumpridos os requisitos subjetivos e objetivos para a obtenção\nda progressão de regime, o advogado de Carlos ingressou\ncom o pedido perante o Juízo de Execução. Deferida a\nprogressão para o regime menos rigoroso, semiaberto, a\nexecução continuou a cumprir seu papel. Passados mais\nalguns anos, Carlos cumpriu o prazo para mais uma\nprogressão de regime.\nNessa hipótese, assinale a alternativa correta.\nA) A legislação determina um prazo de suspensão da contagem de\nprazo após o deferimento da primeira progressão de regime para\nque o apenado possa começar novamente a contagem do prazo\npara o segundo benefício.\nB) A legislação determina um prazo de interrupção da contagem de\nprazo após o deferimento da primeira progressão de regime para\nque o apenado possa começar novamente a contagem do prazo\npara o segundo benefício.\nC) O cálculo de pena para uma posterior progressão de regime de\nCarlos para o regime aberto deve ser feito sobre o total da pena\nimposta na sentença.\nD) O cálculo de pena para uma posterior progressão de regime de\nCarlos para o regime aberto deve ser feito sobre o total da pena\nimposta na sentença, após o período de suspensão da\ncontagem do prazo.\nE) O cálculo de pena para uma posterior progressão de regime de\nCarlos para o regime aberto deve ser feito sobre o tempo de\npena que resta a cumprir.","item_number":61,"source_pages":[19],"answer_in_official_document":"E","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"E","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/e43ddadeaede233fdd62b5d9d1b54b7f81b53ee63ecc067f92f7cd417dc34a25","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Base de cálculo da progressão seguinte","observed_style":"caso_pratico","explanation":"A letra E trabalha a pena remanescente. O cálculo concreto exige marcos de cumprimento, detração e regra temporal de percentuais; confirmar a jurisprudência do STJ para a operação, sem usar o total original indiscriminadamente.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","jurisprudencia_pendente"],"primary_evidence":[{"reference":"lep:111","title":"Lei de Execução Penal","url":"https://www2.camara.leg.br/legin/fed/lei/1980-1987/lei-7210-11-julho-1984-356938-normaatualizada-pl.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"980c833062f81f00251cc0d0f12a4fcde36a04c2658b3826b08d571f7a4f85ea","excerpt_sha256":"e2ced3a407fe05840b5bfab8dfe533ceea0bc12649560ef1b81350a2bdf3cdf2","excerpt_artifact":"fontes-e-excertos.json#/sources/lep/excerpts/111","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"lep:112","title":"Lei de Execução Penal","url":"https://www2.camara.leg.br/legin/fed/lei/1980-1987/lei-7210-11-julho-1984-356938-normaatualizada-pl.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"980c833062f81f00251cc0d0f12a4fcde36a04c2658b3826b08d571f7a4f85ea","excerpt_sha256":"c66dcf8b08a17458efee8277814566bd31610b16802af7fadd364432cdf7f793","excerpt_artifact":"fontes-e-excertos.json#/sources/lep/excerpts/112","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[19]}}}},{"candidate":"fea9d4416051483fa0b0965e624beac542e56291e3945e5462c96af8f9aa455e","expected_status":"under_review","expected_payload":{"raw_text":"62. Ricardo está sendo processado por crime de tráfico de\nentorpecentes e, durante a instrução criminal, descobriu que\nfoi alvo de interceptação telefônica. Em conversa reservada\ncom seu advogado, especialista em matéria penal, pediu para\nque fosse esclarecido como o Superior Tribunal de Justiça tem\nse posicionado acerca da complexidade do tema. Nesse\ncenário, assinale a afirmativa INCORRETA.\nA) Embora não haja previsão na Lei 9.296/96 sobre o\nprocedimento de degravação dos diálogos objeto da\ninterceptação telefônica, é necessário que as degravações das\nescutas sejam feitas por peritos oficiais.\nB) É possível a determinação de interceptações telefônicas com\nbase em denúncia anônima, desde que corroborada por outros\nelementos que confirmem a necessidade da medida\nexcepcional.\nC) A interceptação telefônica só será deferida quando não houver\noutros meios de prova disponíveis à época na qual a medida\ninvasiva foi requerida, sendo ônus da defesa demonstrar\nviolação ao disposto no art. 2º, inciso II, da Lei 9.296/96.\nD) É legítima a prova obtida por meio de interceptação telefônica\npara apuração de delito punido com detenção, se conexo com\noutro crime apenado com reclusão.\nE) Não há necessidade de degravação dos diálogos objeto de\ninterceptação telefônica, em sua integralidade, visto que a Lei\n9.296/96 não faz qualquer exigência nesse sentido.","item_number":62,"source_pages":[20],"answer_in_official_document":"A","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"62. Ricardo está sendo processado por crime de tráfico de\nentorpecentes e, durante a instrução criminal, descobriu que\nfoi alvo de interceptação telefônica. Em conversa reservada\ncom seu advogado, especialista em matéria penal, pediu para\nque fosse esclarecido como o Superior Tribunal de Justiça tem\nse posicionado acerca da complexidade do tema. Nesse\ncenário, assinale a afirmativa INCORRETA.\nA) Embora não haja previsão na Lei 9.296/96 sobre o\nprocedimento de degravação dos diálogos objeto da\ninterceptação telefônica, é necessário que as degravações das\nescutas sejam feitas por peritos oficiais.\nB) É possível a determinação de interceptações telefônicas com\nbase em denúncia anônima, desde que corroborada por outros\nelementos que confirmem a necessidade da medida\nexcepcional.\nC) A interceptação telefônica só será deferida quando não houver\noutros meios de prova disponíveis à época na qual a medida\ninvasiva foi requerida, sendo ônus da defesa demonstrar\nviolação ao disposto no art. 2º, inciso II, da Lei 9.296/96.\nD) É legítima a prova obtida por meio de interceptação telefônica\npara apuração de delito punido com detenção, se conexo com\noutro crime apenado com reclusão.\nE) Não há necessidade de degravação dos diálogos objeto de\ninterceptação telefônica, em sua integralidade, visto que a Lei\n9.296/96 não faz qualquer exigência nesse sentido.","item_number":62,"source_pages":[20],"answer_in_official_document":"A","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"A","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/fea9d4416051483fa0b0965e624beac542e56291e3945e5462c96af8f9aa455e","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Interceptação e degravação","observed_style":"jurisprudencia_em_alternativas","explanation":"A letra A afirma exigência de peritos oficiais que precisa ser confrontada com o precedente específico. Todos os demais enunciados também exigem cotejo quanto a subsidiariedade, ônus de demonstração e encontro fortuito.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","fonte_especial_e_jurisprudencia_pendentes"],"primary_evidence":[],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[20]}}}},{"candidate":"59e63d7a8474c1575f5e5ead54e0419960e84636725622d9234d8619ad277a1c","expected_status":"under_review","expected_payload":{"raw_text":"63. Analise as afirmativas a seguir:\nI. Permite-se a decretação da prisão temporária para o crime de\nepidemia com o resultado morte.\nII. Na falta ou no impedimento do escrivão, qualquer pessoa\ndesignada pela autoridade lavrará o auto de prisão em\nflagrante, depois de prestado o compromisso legal.\nIII. Decretada a prisão preventiva, deverá o órgão emissor da\ndecisão revisar a necessidade de sua manutenção a cada 90\n(noventa) dias, mediante decisão fundamentada, de ofício, sob\npena de tornar a prisão ilegal.\nIV. Nas infrações permanentes, entende-se o agente em flagrante\ndelito enquanto não cessar a permanência.\nAssinale\nA) se apenas as afirmativas I, III e IV estiverem corretas.\nB) se apenas as afirmativas II, III e IV estiverem corretas.\nC) se apenas as afirmativas III e IV estiverem corretas.\nD) se todas as afirmativas estiverem corretas.\nE) se apenas as afirmativas II e III estiverem corretas.","item_number":63,"source_pages":[20],"answer_in_official_document":"D","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"63. Analise as afirmativas a seguir:\nI. Permite-se a decretação da prisão temporária para o crime de\nepidemia com o resultado morte.\nII. Na falta ou no impedimento do escrivão, qualquer pessoa\ndesignada pela autoridade lavrará o auto de prisão em\nflagrante, depois de prestado o compromisso legal.\nIII. Decretada a prisão preventiva, deverá o órgão emissor da\ndecisão revisar a necessidade de sua manutenção a cada 90\n(noventa) dias, mediante decisão fundamentada, de ofício, sob\npena de tornar a prisão ilegal.\nIV. Nas infrações permanentes, entende-se o agente em flagrante\ndelito enquanto não cessar a permanência.\nAssinale\nA) se apenas as afirmativas I, III e IV estiverem corretas.\nB) se apenas as afirmativas II, III e IV estiverem corretas.\nC) se apenas as afirmativas III e IV estiverem corretas.\nD) se todas as afirmativas estiverem corretas.\nE) se apenas as afirmativas II e III estiverem corretas.","item_number":63,"source_pages":[20],"answer_in_official_document":"D","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"D","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/59e63d7a8474c1575f5e5ead54e0419960e84636725622d9234d8619ad277a1c","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Prisões e revisão nonagesimal","observed_style":"afirmativas","explanation":"A III transcreve parte do art. 316, mas não deve ensinar soltura automática no dia 91. As decisões do STF exigem controle fundamentado; a prisão temporária por epidemia com morte ainda exige conferência da Lei 7.960 e dos requisitos cumulativos.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","fonte_especial_e_jurisprudencia_pendentes"],"primary_evidence":[{"reference":"cpp:303","title":"Código de Processo Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"e6e68e8afc1da9aeac8970fb106d7d49e88eec11d67db3b704c8c6db65c2fe0f","excerpt_sha256":"cc26ed5db819c450f4108732a373423533f8d71117432123524a8ed1b03d007f","excerpt_artifact":"fontes-e-excertos.json#/sources/cpp/excerpts/303","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cpp:305","title":"Código de Processo Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"e6e68e8afc1da9aeac8970fb106d7d49e88eec11d67db3b704c8c6db65c2fe0f","excerpt_sha256":"cac704bceff6c0080992485fc0bf53b295ff06d399e0b799a5f95d28800f17d2","excerpt_artifact":"fontes-e-excertos.json#/sources/cpp/excerpts/305","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cpp:316","title":"Código de Processo Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"e6e68e8afc1da9aeac8970fb106d7d49e88eec11d67db3b704c8c6db65c2fe0f","excerpt_sha256":"6a1c9bd2ba6c31bb9011821958cc7df068817db38c160a697c10f441d7de290f","excerpt_artifact":"fontes-e-excertos.json#/sources/cpp/excerpts/316","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"stf6298","title":"Dispositivo de julgamento de 24/08/2023 da ADI 6.298","url":"https://portal.stf.jus.br/processos/downloadTexto.asp?id=5850380&ext=RTF","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"4ee04113e868696c5888451be65bfc143846d64480c7f39bd01bdcc029761754","excerpt_sha256":"9c0f4b2207108f698e5a7f5ef0ef874b9021757d04c8c88d4c55b25159a835d4","excerpt_artifact":"fontes-e-excertos.json#/sources/stf6298/excerpts/document","scope":"Dispositivo integral consultado, não acórdão integral"}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[20]}}}},{"candidate":"c029d472767d55b1514d96e4ed284dff2f2da88be4995639762a2bf771205e90","expected_status":"under_review","expected_payload":{"raw_text":"64. Têm sido recorrentes no Judiciário questionamentos relativos\naos autos de prisão em flagrante lavrados pelas Autoridades\nPoliciais. O Superior Tribunal de Justiça já teve a oportunidade\nde se manifestar várias vezes sobre a prisão em flagrante,\ndeixando registrada sua posição sobre diversos pontos\nimportantes.\nNesse cenário, assinale a afirmativa INCORRETA no tocante\nà posição do Superior Tribunal de Justiça sobre o tema.\nA) No tocante ao flagrante retardado ou à ação controlada, a\nausência de autorização judicial não tem o condão de tornar\nilegal a prisão em flagrante postergado, uma vez que o instituto\nvisa a proteger o trabalho investigativo, afastando a eventual\nresponsabilidade criminal ou administrativa por parte do\nagente policial.\nB) Uma vez decretada a prisão preventiva, fica superada a tese\nde excesso de prazo na comunicação do flagrante.\nC) Realizada a conversão da prisão em flagrante em preventiva,\nfica superada a alegação de nulidade porventura existente em\nrelação à ausência de audiência de custódia.\nD) Ocorre nulidade no auto de prisão em flagrante quando da\nausência de assistência por advogado e não seja oportunizado\nao conduzido o direito de ser assistido por defensor técnico,\nainda que a autoridade policial registre os direitos do preso\nprevistos no art. 5º, LXIII, da Constituição Federal.\nE) Não há nulidade da audiência de custódia por suposta violação\nda Súmula Vinculante 11 do STF, quando devidamente\njustificada a necessidade do uso de algemas pelo segregado.","item_number":64,"source_pages":[20],"answer_in_official_document":"D","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"64. Têm sido recorrentes no Judiciário questionamentos relativos\naos autos de prisão em flagrante lavrados pelas Autoridades\nPoliciais. O Superior Tribunal de Justiça já teve a oportunidade\nde se manifestar várias vezes sobre a prisão em flagrante,\ndeixando registrada sua posição sobre diversos pontos\nimportantes.\nNesse cenário, assinale a afirmativa INCORRETA no tocante\nà posição do Superior Tribunal de Justiça sobre o tema.\nA) No tocante ao flagrante retardado ou à ação controlada, a\nausência de autorização judicial não tem o condão de tornar\nilegal a prisão em flagrante postergado, uma vez que o instituto\nvisa a proteger o trabalho investigativo, afastando a eventual\nresponsabilidade criminal ou administrativa por parte do\nagente policial.\nB) Uma vez decretada a prisão preventiva, fica superada a tese\nde excesso de prazo na comunicação do flagrante.\nC) Realizada a conversão da prisão em flagrante em preventiva,\nfica superada a alegação de nulidade porventura existente em\nrelação à ausência de audiência de custódia.\nD) Ocorre nulidade no auto de prisão em flagrante quando da\nausência de assistência por advogado e não seja oportunizado\nao conduzido o direito de ser assistido por defensor técnico,\nainda que a autoridade policial registre os direitos do preso\nprevistos no art. 5º, LXIII, da Constituição Federal.\nE) Não há nulidade da audiência de custódia por suposta violação\nda Súmula Vinculante 11 do STF, quando devidamente\njustificada a necessidade do uso de algemas pelo segregado.","item_number":64,"source_pages":[20],"answer_in_official_document":"D","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"D","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/c029d472767d55b1514d96e4ed284dff2f2da88be4995639762a2bf771205e90","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Flagrante, custódia e defensor","observed_style":"jurisprudencia_em_alternativas","explanation":"O gabarito D reúne nulidade por assistência, mas as demais teses sobre superação de vícios e ausência de audiência não devem ser tratadas como absolutas. Confrontar a decisão atual do STF e precedentes específicos do STJ, inclusive controle de maus-tratos e algemas.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","jurisprudencia_pendente"],"primary_evidence":[{"reference":"cpp:310","title":"Código de Processo Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"e6e68e8afc1da9aeac8970fb106d7d49e88eec11d67db3b704c8c6db65c2fe0f","excerpt_sha256":"ae697aa4bc579a197fb2a5eedd9e12f7d829e25d0d73e5bdd99af431a045879d","excerpt_artifact":"fontes-e-excertos.json#/sources/cpp/excerpts/310","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cf:5","title":"Constituição Federal","url":"https://www2.camara.leg.br/legin/fed/consti/1988/constituicao-1988-5-outubro-1988-322142-normaatualizada-pl.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"a8de1643589cf9fb199bb58a0cf4a6acd63c35ed377843d8240ca500b7e1f2c1","excerpt_sha256":"e5ef391571d44a08d3ef196401fcec34b6b48bda6d377684ec03bbe0b81dbb89","excerpt_artifact":"fontes-e-excertos.json#/sources/cf/excerpts/5","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"stf6298","title":"Dispositivo de julgamento de 24/08/2023 da ADI 6.298","url":"https://portal.stf.jus.br/processos/downloadTexto.asp?id=5850380&ext=RTF","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"4ee04113e868696c5888451be65bfc143846d64480c7f39bd01bdcc029761754","excerpt_sha256":"9c0f4b2207108f698e5a7f5ef0ef874b9021757d04c8c88d4c55b25159a835d4","excerpt_artifact":"fontes-e-excertos.json#/sources/stf6298/excerpts/document","scope":"Dispositivo integral consultado, não acórdão integral"}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[20]}}}}]$idecan_review_batch$::jsonb) loop
    select * into stored from public.question_corpus_candidates where id=change->>'candidate' for update;
    if not found then raise exception 'Candidato não encontrado; aplique antes o acervo de 200 itens'; end if;
    if stored.content_status=change->>'next_status' and stored.payload=change->'next_payload' then continue; end if;
    if stored.content_status is distinct from change->>'expected_status'
      or stored.payload is distinct from change->'expected_payload' then
      raise exception 'Revisão desatualizada: decisão existente preservada; recarregue o candidato';
    end if;
    if stored.content_status <> 'under_review' then raise exception 'Decisão anterior protegida'; end if;
    if change->'next_payload'->'raw_text' is distinct from stored.payload->'raw_text' then
      raise exception 'Extração original protegida';
    end if;
    if change->'next_payload' ? 'publication'
      or change#>>'{next_payload,individual_review,publication_approved}' is distinct from 'false' then
      raise exception 'Este lote não permite publicação';
    end if;
    insert into public.question_corpus_review_audit(candidate_id,previous_status,next_status,previous_payload,next_payload,reviewer_id)
    values(stored.id,stored.content_status,change->>'next_status',stored.payload,change->'next_payload',auth.uid());
    update public.question_corpus_candidates set content_status=change->>'next_status',payload=change->'next_payload' where id=stored.id;
  end loop;
end $review$;
commit;
-- reviewed significa parecer registrado, não autorização de publicação.
select s.title,c.content_status,count(*) as candidates
from public.question_corpus_sources s join public.question_corpus_candidates c on c.corpus_id=s.id
where s.id in ('56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe','a835d92983601375c77355a50f68bdc77092e4fb88fdb9686ff453b8ed2fd57d')
group by s.title,c.content_status order by s.title,c.content_status;
